1	package com.maritime.platform.gateway.security;
2	
3	import java.time.Duration;
4	import java.time.temporal.ChronoUnit;
5	import java.util.ArrayList;
6	import java.util.List;
7	
8	import org.springframework.beans.factory.InitializingBean;
9	import org.springframework.boot.context.properties.ConfigurationProperties;
10	import org.springframework.validation.annotation.Validated;
11	
12	import jakarta.validation.Valid;
13	import jakarta.validation.constraints.Min;
14	import jakarta.validation.constraints.NotBlank;
15	import jakarta.validation.constraints.NotEmpty;
16	import jakarta.validation.constraints.NotNull;
17	
18	@ConfigurationProperties(prefix = "maritime.gateway.security")
19	@Validated
20	public class GatewaySecurityProperties implements InitializingBean {
21	
22	    private AuthMode defaultAuthMode = AuthMode.JWT;
23	
24	    private List<String> publicPaths = new ArrayList<>();
25	
26	    @Valid
27	    private List<RoutePolicy> routes = new ArrayList<>();
28	
29	    @Valid
30	    private Jwt jwt = new Jwt();
31	
32	    @Valid
33	    private Hmac hmac = new Hmac();
34	
35	    public AuthMode getDefaultAuthMode() { return defaultAuthMode; }
36	    public void setDefaultAuthMode(AuthMode defaultAuthMode) { this.defaultAuthMode = defaultAuthMode; }
37	
38	    public List<String> getPublicPaths() { return publicPaths; }
39	    public void setPublicPaths(List<String> publicPaths) { this.publicPaths = publicPaths; }
40	
41	    public List<RoutePolicy> getRoutes() { return routes; }
42	    public void setRoutes(List<RoutePolicy> routes) { this.routes = routes; }
43	
44	    public Jwt getJwt() { return jwt; }
45	    public void setJwt(Jwt jwt) { this.jwt = jwt; }
46	
47	    public Hmac getHmac() { return hmac; }
48	    public void setHmac(Hmac hmac) { this.hmac = hmac; }
49	
50	    @Override
51	    public void afterPropertiesSet() {
52	        if (defaultAuthMode == AuthMode.JWT_AND_HMAC) {
53	            throw new IllegalStateException(
54	                    "maritime.gateway.security.default-auth-mode=JWT_AND_HMAC is reserved and not yet implemented");
55	        }
56	        for (RoutePolicy rp : routes) {
57	            if (rp.authMode == null) {
58	                throw new IllegalStateException(
59	                        "Route '" + rp.id + "' is missing required auth-mode. "
60	                        + "Set maritime.gateway.security.routes[" + routes.indexOf(rp) + "].auth-mode "
61	                        + "to one of: JWT, HMAC, JWT_OR_HMAC, NONE");
62	            }
63	            if (rp.authMode == AuthMode.JWT_AND_HMAC) {
64	                throw new IllegalStateException(
65	                        "Route '" + rp.id + "' uses JWT_AND_HMAC which is reserved and not yet implemented");
66	            }
67	        }
68	
69	        // Fail closed: auth mode must be consistent with enabled flags.
70	        // Without this check, a route requesting JWT/HMAC authentication
71	        // would silently forward requests when the corresponding filter
72	        // is not registered due to jwt.enabled=false / hmac.enabled=false.
73	        validateAuthModeConsistency(defaultAuthMode, "default-auth-mode");
74	        for (RoutePolicy rp : routes) {
75	            validateAuthModeConsistency(rp.authMode, "route '" + rp.id + "'");
76	        }
77	
78	        if (jwt.enabled) {
79	            if (jwt.secret == null || jwt.secret.isBlank()) {
80	                throw new IllegalStateException(
81	                        "maritime.gateway.security.jwt.secret must not be blank when jwt.enabled=true");
82	            }
83	            if (jwt.issuer == null || jwt.issuer.isBlank()) {
84	                throw new IllegalStateException(
85	                        "maritime.gateway.security.jwt.issuer must not be blank when jwt.enabled=true");
86	            }
87	        }
88	        if (hmac.enabled) {
89	            if (hmac.timestampTolerance == null || hmac.timestampTolerance.isNegative()) {
90	                throw new IllegalStateException(
91	                        "maritime.gateway.security.hmac.timestamp-tolerance must be a positive duration when hmac.enabled=true");
92	            }
93	            if (hmac.nonceTtl == null || hmac.nonceTtl.isNegative()) {
94	                throw new IllegalStateException(
95	                        "maritime.gateway.security.hmac.nonce-ttl must be a positive duration when hmac.enabled=true");
96	            }
97	        }
98	    }
99	
100	    private void validateAuthModeConsistency(AuthMode mode, String target) {
101	        switch (mode) {
102	            case JWT:
103	                if (!jwt.enabled) {
104	                    throw new IllegalStateException(
105	                            target + " is JWT but maritime.gateway.security.jwt.enabled is not true");
106	                }
107	                break;
108	            case HMAC:
109	                if (!hmac.enabled) {
110	                    throw new IllegalStateException(
111	                            target + " is HMAC but maritime.gateway.security.hmac.enabled is not true");
112	                }
113	                break;
114	            case JWT_OR_HMAC:
115	                if (!jwt.enabled || !hmac.enabled) {
116	                    throw new IllegalStateException(
117	                            target + " is JWT_OR_HMAC but requires both "
118	                            + "maritime.gateway.security.jwt.enabled=true and "
119	                            + "maritime.gateway.security.hmac.enabled=true");
120	                }
121	                break;
122	            case NONE:
123	            case JWT_AND_HMAC:
124	                // NONE: no auth components required.
125	                // JWT_AND_HMAC: already rejected above.
126	                break;
127	        }
128	    }
129	
130	    // ---------- nested types ----------
131	
132	    @Validated
133	    public static class RoutePolicy {
134	
135	        @NotBlank
136	        private String id;
137	
138	        @NotEmpty
139	        private List<String> paths = new ArrayList<>();
140	
141	        private List<String> methods = new ArrayList<>();
142	
143	        @NotNull
144	        private AuthMode authMode;
145	
146	        public String getId() { return id; }
147	        public void setId(String id) { this.id = id; }
148	        public List<String> getPaths() { return paths; }
149	        public void setPaths(List<String> paths) { this.paths = paths; }
150	        public List<String> getMethods() { return methods; }
151	        public void setMethods(List<String> methods) { this.methods = methods; }
152	        public AuthMode getAuthMode() { return authMode; }
153	        public void setAuthMode(AuthMode authMode) { this.authMode = authMode; }
154	    }
155	
156	    @Validated
157	    public static class Jwt {
158	
159	        private boolean enabled;
160	
161	        private String secret;
162	
163	        private boolean encrypted;
164	
165	        private String issuer = "";
166	
167	        @Min(0)
168	        private int clockSkewSeconds = 30;
169	
170	        @Valid
171	        private Claims claims = new Claims();
172	
173	        @Valid
174	        private RedisKeys redisKeys = new RedisKeys();
175	
176	        @Valid
177	        private Validation validation = new Validation();
178	
179	        @Valid
180	        private JwtNonce nonce = new JwtNonce();
181	
182	        public boolean isEnabled() { return enabled; }
183	        public void setEnabled(boolean enabled) { this.enabled = enabled; }
184	        public String getSecret() { return secret; }
185	        public void setSecret(String secret) { this.secret = secret; }
186	        public boolean isEncrypted() { return encrypted; }
187	        public void setEncrypted(boolean encrypted) { this.encrypted = encrypted; }
188	        public String getIssuer() { return issuer; }
189	        public void setIssuer(String issuer) { this.issuer = issuer; }
