542	    @DisplayName("JWT authentication manager state validation (auto-wired)")
543	    class JwtAuthManagerStateValidation {
544	
545	        private static final String SECRET = "test-secret-with-minimum-length-256-bits!!";
546	        private static final String ISSUER = "test-issuer";
547	
548	        private SecretKey signingKey() {
549	            return Keys.hmacShaKeyFor(SECRET.getBytes(StandardCharsets.UTF_8));
550	        }
551	
552	        private String createToken(String userId, String sessionId, String jti) {
553	            Instant now = Instant.now();
554	            return Jwts.builder()
555	                    .issuer(ISSUER)
556	                    .id(jti)
557	                    .claim("userId", userId)
558	                    .claim("sessionId", sessionId)
559	                    .issuedAt(Date.from(now))
560	                    .expiration(Date.from(now.plusSeconds(3600)))
561	                    .signWith(signingKey())
562	                    .compact();
563	        }
564	
565	        @Test
566	        @DisplayName("valid token with Redis session succeeds")
567	        void validTokenWithSessionSucceeds() {
568	            createRunner().run(ctx -> {
569	                var manager = ctx.getBean(JwtAuthenticationManager.class);
570	                var props = ctx.getBean(GatewaySecurityProperties.class);
571	                var redisOps = (ReactiveRedisOperations<String, String>) ctx.getBean(ReactiveRedisOperations.class);
572	
573	                String sessionId = "auto-session-ok";
574	                String sessionKey = props.getJwt().getRedisKeys().getSessionPrefix() + sessionId;
575	                redisOps.opsForValue().set(sessionKey, "1").block();
576	
577	                String token = createToken("user-ok", sessionId, UUID.randomUUID().toString());
578	
579	                StepVerifier.create(manager.authenticate(token))
580	                        .assertNext(user -> {
581	                            assertThat(user.userId()).isEqualTo("user-ok");
582	                            assertThat(user.sessionId()).isEqualTo(sessionId);
583	                        })
584	                        .verifyComplete();
585	
586	                redisOps.delete(sessionKey).block();
587	            });
588	        }
