                assertThat(ctx).hasNotFailed();
                assertThat(ctx).getBean(GatewaySecurityProperties.class).getDefaultAuthMode()
                        .isEqualTo(com.maritime.platform.gateway.security.AuthMode.JWT_OR_HMAC);
            });
        }
    }
}

